{"command":"create","path":"/root/output/css/style.css","file_text":":root {
  --bg: #0b1020;
  --panel: #111a33;
  --panel-2: #0f1730;
  --text: #e8ecff;
  --muted: rgba(232, 236, 255, 0.72);
  --grid: rgba(232, 236, 255, 0.09);
  --selected: #ffd166;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background:
    radial-gradient(1200px 500px at 25% 5%, rgba(122, 162, 255, 0.25), transparent 60%),
    radial-gradient(900px 450px at 85% 0%, rgba(255, 209, 102, 0.18), transparent 55%),
    var(--bg);
  color: var(--text);
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial;
}

.header {
  border-bottom: 1px solid var(--grid);
  background: linear-gradient(180deg, rgba(17, 26, 51, 0.88), rgba(17, 26, 51, 0.55));
  backdrop-filter: blur(6px);
}

.header-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 18px 18px 14px;
}

h1 {
  font-size: 18px;
  font-weight: 650;
  margin: 0 0 6px;
  letter-spacing: 0.2px;
}

.subtle {
  font-size: 13px;
  color: var(--muted);
}

.layout {
  max-width: 1280px;
  margin: 0 auto;
  padding: 16px 18px 24px;
  display: flex;
  gap: 14px;
  align-items: stretch;
}

.pane {
  background: linear-gradient(180deg, rgba(17, 26, 51, 0.92), rgba(15, 23, 48, 0.9));
  border: 1px solid var(--grid);
  border-radius: 12px;
  padding: 12px 12px 10px;
  min-height: 640px;
  box-shadow: 0 12px 50px rgba(0, 0, 0, 0.38);
}

.pane-title {
  margin: 4px 6px 10px;
  font-size: 14px;
  font-weight: 650;
  letter-spacing: 0.2px;
  color: rgba(232, 236, 255, 0.92);
}

.pane-left {
  flex: 1.05;
}

.pane-right {
  flex: 0.95;
}

.chart {
  width: 100%;
  height: 560px;
  border-radius: 10px;
  background: rgba(8, 12, 24, 0.35);
  border: 1px solid rgba(232, 236, 255, 0.07);
  overflow: hidden;
}

.hint {
  margin: 10px 6px 0;
  font-size: 12.5px;
  color: var(--muted);
}

.selection-info {
  margin: 0 6px 10px;
  padding: 10px 10px;
  border-radius: 10px;
  background: rgba(8, 12, 24, 0.42);
  border: 1px solid rgba(232, 236, 255, 0.07);
  color: rgba(232, 236, 255, 0.9);
  font-size: 13px;
  line-height: 1.35;
  min-height: 44px;
}

.table-wrap {
  height: 560px;
  overflow: auto;
  border-radius: 10px;
  border: 1px solid rgba(232, 236, 255, 0.07);
  background: rgba(8, 12, 24, 0.35);
}

.stock-table {
  width: 100%;
  border-collapse: collapse;
}

.stock-table thead th {
  position: sticky;
  top: 0;
  background: rgba(15, 23, 48, 0.95);
  backdrop-filter: blur(6px);
  z-index: 2;
  text-align: left;
  font-size: 12.5px;
  color: rgba(232, 236, 255, 0.85);
  padding: 10px 10px;
  border-bottom: 1px solid rgba(232, 236, 255, 0.11);
}

.stock-table td {
  padding: 9px 10px;
  font-size: 12.5px;
  color: rgba(232, 236, 255, 0.88);
  border-bottom: 1px solid rgba(232, 236, 255, 0.08);
}

.stock-table tr:hover td {
  background: rgba(122, 162, 255, 0.10);
}

.stock-table tr.selected td {
  background: rgba(255, 209, 102, 0.16);
  outline: 1px solid rgba(255, 209, 102, 0.5);
}

.stock-table .num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.tooltip {
  position: absolute;
  pointer-events: none;
  padding: 10px 10px;
  border-radius: 10px;
  background: rgba(10, 14, 28, 0.92);
  border: 1px solid rgba(232, 236, 255, 0.14);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
  color: rgba(232, 236, 255, 0.95);
  width: 240px;
}

.tooltip .tt-ticker {
  font-weight: 750;
  letter-spacing: 0.3px;
  margin-bottom: 2px;
}

.tooltip .tt-name {
  color: rgba(232, 236, 255, 0.9);
  margin-bottom: 2px;
}

.tooltip .tt-sector {
  color: rgba(232, 236, 255, 0.72);
}

@media (max-width: 980px) {
  .layout { flex-direction: column; }
  .pane { min-height: auto; }
  .chart, .table-wrap { height: 520px; }
}
