        market_cap = None
        if mc_raw and mc_raw.lower() != 'nan':
            try:
                market_cap = float(mc_raw)
            except ValueError:
                market_cap = None

        stocks.append({
            'ticker': ticker,
            'sector': sector,
            'name': name,
            'marketCap': market_cap,
        })

